<script setup>
import {computed,ref} from 'vue'
import Icon from './Icon.vue'
const props=defineProps({data:Object,member:Object})
const category=ref(props.member.role==='Student'?props.member.category:'All')
const board=computed(()=>props.data.leaderboard.filter(s=>category.value==='All'||s.category===category.value).map((s,i)=>({...s,rank:i+1})))
</script>
<template><div class="page-heading"><div><div class="eyebrow">PROGRESS DESERVES A LITTLE CELEBRATION</div><h1>The monthly learning challenge.</h1><p>{{data.month}} · Practice a little. Learn together. Cheer each other on.</p></div><span class="stat-icon peach"><Icon name="Award" :size="30"/></span></div><section class="challenge-banner"><div><span class="eyebrow">{{member.role==='Student'?'YOUR PERSONAL MILESTONE':'CAMPUS PARTICIPATION'}}</span><h2>{{member.role==='Student'?'You’re #'+data.ownRank?.rank+' in your programme.':data.leaderboard.length+' learners making progress.'}}</h2><p>Monthly completion: {{data.totals.completion}}% · Average attendance: {{data.totals.attendance}}%</p></div><Icon name="Award" :size="80"/></section><div class="insight-grid"><section class="panel"><div class="section-heading"><h2>Learning leaderboard</h2><select v-if="member.role!=='Student'" v-model="category" aria-label="Leaderboard programme"><option>All</option><option v-for="c in data.categories">{{c.name}}</option></select></div><div v-for="s in board.slice(0,15)" :key="s.student" class="teacher-metric"><span class="rank-circle">{{s.rank}}</span><div><strong>{{s.student===member.name?'You · ':''}}{{s.alias}}</strong><small>{{s.category}} · {{s.completion}}% monthly completion</small></div><b>{{s.score}} pts</b></div></section><section class="panel"><span class="stat-icon mint"><Icon name="Sprout" :size="26"/></span><h2>Reward the effort.</h2><p>Score = 50% quiz average + 30% monthly lesson completion + 20% attendance. All scores shown here are synthetic.</p><p>Programme filters compare learners at a similar level. Public views show learner aliases; payment amounts never affect scores.</p><h3>Your next milestone</h3><p>Complete this week’s practice, attend your next session, and ask one good question.</p><p class="field-help">This is a demo competition. Production scoring, consent, anti-cheating checks and teacher review must be connected to real Frappe learning records before awards are issued.</p></section></div></template>
